/* AstroHealth offline cockpit. Synthetic preview is isolated from authenticated telemetry. */
'use strict';
const $=s=>document.querySelector(s), esc=UI.escape;
const pages=[['dashboard','DASHBOARD','TỔNG QUAN SỨC KHỎE'],['vitals','VITALS','CHỈ SỐ SINH TỒN'],['organs','ORGANS','HỆ CƠ QUAN'],['sleep','SLEEP','GIẤC NGỦ & HÀNH VI'],['nutrition','NUTRITION','DINH DƯỠNG'],['environment','ENV / RAD','MÔI TRƯỜNG & BỨC XẠ'],['ai','AI / XAI','PHÂN TÍCH & GIẢI THÍCH'],['alerts','ALERTS','CẢNH BÁO'],['history','HISTORY','LỊCH SỬ & PHÂN TÍCH'],['reports','REPORTS','BÁO CÁO'],['assistant','ASSISTANT','TRỢ LÝ THEO QUY TẮC'],['sync','SYNC','ĐỒNG BỘ MẶT ĐẤT'],['system','SYSTEM','HỆ THỐNG / QUẢN TRỊ'],['design','DESIGN','COMPONENT STYLE GUIDE']];
const organs=[['cardio','TIM MẠCH'],['resp','HÔ HẤP'],['musculoskeletal','CƠ XƯƠNG'],['neuro','THẦN KINH'],['immune','MIỄN DỊCH']];
const state={page:'dashboard',crew:0,crews:[],organ:'cardio',bodyExpanded:false,vitals:[],alerts:[],token:null,refresh:null,user:null,health:null,online:false,freeze:false,cursor:false,range:7,history:null,historyMetric:'hr',socket:null,navHistory:[],lastInference:null,records:{},syncStatus:null,bodyStatus:null,accounts:null,audio:false};
const API=location.protocol==='file:'?'http://127.0.0.1:8000':'';
let toastTimer, renderEpoch=0;let soundContext;const soundedAlerts=new Set();
function alertSound(){if(!state.audio)return;try{soundContext ||= new AudioContext();soundContext.resume();const oscillator=soundContext.createOscillator(),gain=soundContext.createGain();oscillator.connect(gain);gain.connect(soundContext.destination);oscillator.frequency.value=660;gain.gain.value=.06;oscillator.start();oscillator.stop(soundContext.currentTime+.2);}catch{toast('Âm báo chưa sẵn sàng.');}}
const markupCache=new Map();
function setMarkup(selector,html){if(markupCache.get(selector)!==html){const el=$(selector);if(el){el.innerHTML=html;markupCache.set(selector,html);}}}
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',4200);}
function modal(title,html){$('#modal-title').textContent=title;$('#modal-body').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();}
async function request(path,options={}){
  const response=await fetch(API+'/api/v1'+path,{...options,headers:{'Content-Type':'application/json',...(state.token?{Authorization:'Bearer '+state.token}:{}),...options.headers},signal:AbortSignal.timeout(12000)});
  if(response.status===401&&state.refresh&&!['/auth/login','/auth/setup','/auth/setup-status','/auth/self-register','/auth/refresh'].includes(path)){
    const renewed=await fetch(API+'/api/v1/auth/refresh',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({refresh_token:state.refresh})});
    if(renewed.ok){const tokens=await renewed.json();state.token=tokens.access_token;state.refresh=tokens.refresh_token;return request(path,options);}
    clearSession();throw Error('Phiên hết hạn. Vui lòng đăng nhập lại.');
  }
  if(!response.ok){let detail;try{detail=(await response.json()).detail;}catch{detail=response.statusText;}throw Error(typeof detail==='string'?detail:JSON.stringify(detail));}
  return response.json();
}
function clearSession(){state.socket?.close();state.socket=null;state.token=null;state.refresh=null;state.user=null;state.vitals=[];state.alerts=[];state.crews=[];state.crew=0;state.records={};state.history=null;state.lastInference=null;state.syncStatus=null;state.bodyStatus=null;state.accounts=null;}
function selected(){return state.crews[state.crew]||{id:'unavailable',name:'Không có dữ liệu',callsign:'—'};}
function canCrewDetail(){return state.user?.role!=='Ground Control Operator';}
function canManageAccounts(){return ['Medical Officer','Admin'].includes(state.user?.role);}
function values(){return state.token?state.vitals:[];}
function val(metric){const row=values().find(r=>r.metric===metric);return row?row.value:'—';}
function alertValues(){return state.token?state.alerts:[];}
function alertHTML(alert){return `<div class="alert-row ${alert.level==='Critical'||alert.level==='Warning'?'warning':'caution'}"><strong>${esc(alert.level.toUpperCase())} / ${esc(alert.metric.toUpperCase())}</strong><p>${esc(alert.rule_id||'GROUND LINK UNAVAILABLE')}</p><small>${esc(alert.source_type.toUpperCase())} / ${esc(alert.status.toUpperCase())} / ${esc(alert.created_at.slice(11,19))} UTC</small><div class="alert-actions"><button data-ack="${esc(alert.id)}" ${alert.status!=='open'?'disabled':''}>ACK</button><button data-why="${esc(alert.id)}">WHY?</button></div></div>`;}
function renderShell(){
  setMarkup('#crew-list',state.crews.map((c,i)=>`<button class="crew-button ${i===state.crew?'active':''}" data-crew="${i}" aria-pressed="${i===state.crew}"><span class="crew-icon">${String(i+1).padStart(2,'0')}</span><span>${esc(c.name||c.callsign)}</span><small>${esc(c.callsign)} / ${c.is_demo?'DEMO PROFILE':'LOCAL PROFILE'}</small></button>`).join('')||'<div class="empty">Chưa có hồ sơ phi hành đoàn.</div>');
  $('#crew-count').textContent=String(state.crews.length).padStart(2,'0');
  setMarkup('#nav',pages.map(([id,label],i)=>`<button data-go="${id}" class="${state.page===id?'active':''}" aria-current="${state.page===id?'page':'false'}"><span>${String(i+1).padStart(2,'0')} / ${{dashboard:'H',vitals:'V',organs:'O',sleep:'S',nutrition:'N',environment:'E',ai:'X',alerts:'A',history:'T',reports:'R',assistant:'I',sync:'Y',system:'Z',design:'D'}[id]}</span>${label}</button>`).join(''));
  const p=pages.find(p=>p[0]===state.page)||pages[0];$('#page-title').textContent=p[2];$('#page-eyebrow').textContent=String(pages.indexOf(p)+1).padStart(2,'0')+' / '+p[1];
  $('#selected-name').textContent=state.crews.length?selected().name||selected().callsign:'CHƯA CHỌN PHI HÀNH GIA';$('#selected-code').textContent=state.crews.length?selected().callsign+' / LOCAL PROFILE':'NO CREW DATA';
  $('#mission-name').textContent=state.crews.length?selected().mission_id+' / LOCAL PROFILE':'NO MISSION SELECTED';
  $('#user-label').textContent=state.user?state.user.role.toUpperCase():'CHƯA ĐĂNG NHẬP';
  $('#login-open').textContent=state.user?'ĐĂNG XUẤT / '+state.user.username:'ĐĂNG NHẬP [L]';
  $('#register-open').textContent=canManageAccounts()?'TẠO TÀI KHOẢN':'ĐĂNG KÝ';
  $('#register-open').hidden=Boolean(state.user&&!canManageAccounts());
  $('#backend-status').textContent=state.online?'▣ API LOCAL / '+state.health?.mode?.toUpperCase():'▧ BACKEND OFFLINE';
  $('#link-status').textContent=state.health?.ground==='connected'?'▣ GROUND: CONNECTED':'△ GROUND: NO CONTACT';
  $('#source-banner').textContent=state.vitals.length?'MEASURED DATA':'CHƯA CÓ DỮ LIỆU ĐO';
  $('#freeze').disabled=true;$('#cursor').disabled=true;
  renderTelemetry();
}
function renderTelemetry(){
  const rows=values();const get=m=>rows.find(r=>r.metric===m);
  $('#source-banner').textContent=rows.length?'MEASURED DATA':'CHƯA CÓ DỮ LIỆU ĐO';
  setMarkup('#vital-tiles',[['hr','HEART RATE','bpm'],['bp','BLOOD PRESSURE','mmHg'],['spo2','SpO₂','%'],['rr','RESPIRATION','/min'],['temp','TEMPERATURE','°C'],['hrv','HRV / RMSSD','ms']].map(([m,label,unit])=>{const r=get(m==='bp'?'sbp':m),dbp=get('dbp');const source=m==='bp'&&r?.source_type!==dbp?.source_type?'MIXED SOURCES':r?.source_type?.toUpperCase()||'INSUFFICIENT DATA';return UI.value(label,m==='bp'?val('sbp')+'/'+val('dbp'):val(m),unit,source,r?.stale||(m==='bp'&&dbp?.stale));}).join(''));
  const alerts=alertValues().filter(a=>a.status!=='resolved');for(const alert of alerts){if(alert.status==='open'&&!soundedAlerts.has(alert.id)){alertSound();soundedAlerts.add(alert.id);}}$('#alert-count').textContent=alerts.length;
  setMarkup('#alert-preview',alerts.slice(0,3).map(alertHTML).join('')||(state.vitals.length===0?'<div class="empty">Chưa có dữ liệu đo cho hồ sơ này. Không đủ dữ liệu để đánh giá.</div>':'<div class="empty">Không có cảnh báo đang mở.</div>'));
  for(const [id,levels] of [['master-warning',['Critical']],['master-caution',['Warning','Watch']]]){const n=alerts.filter(a=>levels.includes(a.level)&&a.status==='open').length;$('#'+id).classList.toggle('pending',n>0);$('#'+id+' small').textContent=n?n+' UNACKNOWLEDGED / PRESS TO ACK':'NO UNACKNOWLEDGED ALERTS';}
}
function organStatus(id){return state.bodyStatus?.[id]?.status||'insufficient_data';}
function statusLabel(status){return status==='warning'?'▲ WARNING':status==='watch'?'△ WATCH':status==='normal'?'● NORMAL':'▧ CHƯA ĐỦ DỮ LIỆU';}
function dashboard(){
  const currentName=organs.find(o=>o[0]===state.organ)?.[1]||'HỆ CƠ QUAN';
  const currentStatus=organStatus(state.organ);
  const metrics=state.bodyStatus?.[state.organ]?.metrics||[];
  const metricRows=metrics.length?metrics.map(r=>`<div class='prop-row'><span class='prop-key'>${esc(r.metric.toUpperCase())}</span><b class='prop-val'>${esc(r.value)} ${esc(r.unit)}</b></div>`).join(''):'<div class=empty>Chưa có phép đo phù hợp.</div>';
  return `<div class='overview'><section class='panel body-panel unity-ide-panel'>
    <div class='panel-title unity-ide-title'><div class='title-left'><span class='ide-tab active'>HUMAN BODY / SYSTEM STATUS</span><span class='source'>${values().length?'MEASURED':'NO MEASURED DATA'}</span></div><span class='unknown'>${statusLabel(currentStatus)}</span></div>
    <div class='body-workspace unity-workspace'>
      <div class='ide-pane ide-hierarchy'><div class='pane-header'><span>HIERARCHY / HỆ CƠ QUAN</span><span class='badge'>05</span></div><div class='organ-list'>${organs.map(([id,name],i)=>`<button data-organ='${id}' class='${state.organ===id?'active':''}'><span class='status-dot ${organStatus(id)==='warning'?'warning':'unknown'}'></span><span class='organ-num'>${String(i+1).padStart(2,'0')}</span><span class='organ-name'>${name}</span><small class='${organStatus(id)==='warning'?'warning':'unknown'}'>${statusLabel(organStatus(id))}</small></button>`).join('')}</div></div>
      ${UI.bodyMap(state.organ)}
      <div class='ide-pane ide-inspector'><div class='pane-header'><span>INSPECTOR / TELEMETRY</span><span class='badge'>${metrics.length?'MEASURED':'NO DATA'}</span></div><div class='inspector-content'><div class='inspector-group'><div class='group-title'>${esc(currentName)}</div><div class='status-line ${currentStatus==='warning'?'warning':'unknown'}'>${statusLabel(currentStatus)}</div><p>${state.crews.length?'Chỉ hiển thị phép đo thực đã nhận. Chưa có đánh giá lâm sàng đã kiểm chứng.':'Chưa có hồ sơ phi hành đoàn. Đăng nhập để xem hồ sơ được cấp.'}</p></div><div class='inspector-group'><div class='group-title'>PHÉP ĐO CỦA HỆ CƠ QUAN</div>${metricRows}</div></div></div>
    </div>
    <div class='body-controls unity-bottom-toolbar'><div class='toolbar-left'><button data-action='body-zoom'>MỞ RỘNG MÔ HÌNH 3D ↗</button><button data-action='organ-detail' ${state.crews.length?'':'disabled'}>CHI TIẾT HỆ CƠ QUAN ↗</button><button data-go='vitals'>VITALS ↗</button><button data-action='event' ${state.crews.length?'':'disabled'}>ĐÁNH DẤU EVENT</button></div><div class='toolbar-right'><span>MAN / mattmerk · CC BY-SA 3.0 // OFFLINE 3D</span></div></div>
  </section><div class='summary-grid'>${[['GIẤC NGỦ','sleep'],['DINH DƯỠNG','nutrition'],['MÔI TRƯỜNG','environment'],['LỊCH SỬ','history']].map(([name,page],i)=>`<section class='panel summary-card'><h3>${String(i+1).padStart(2,'0')} / ${name}</h3><strong>— <small>CHƯA CÓ DỮ LIỆU</small></strong><p>Xem trang chi tiết để nhập hoặc kiểm tra bản ghi có nguồn.</p><button data-go='${page}'>MỞ ${name} ↗</button></section>`).join('')}</div></div>`;
}
function metricTable(){return values().length?`<table><thead><tr><th>METRIC</th><th>VALUE</th><th>UNIT</th><th>SOURCE / QUALITY</th><th>UTC</th></tr></thead><tbody>${values().map(r=>`<tr><td>${esc(r.metric.toUpperCase())}</td><td class="numeric">${esc(r.value)}</td><td>${esc(r.unit)}</td><td>${esc(r.source_type)} / ${esc(r.quality_score)}${r.stale?' / STALE':''}</td><td>${esc(r.ts_utc.slice(11,19))}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">Chưa có phép đo thực. Các chỉ số để trống.</div>';}
function plot(rows){if(!rows?.length)return '<div class="empty">Không có dữ liệu trong khoảng được chọn.</div>';const vals=rows.map(r=>r.value),lo=Math.min(...vals)-2,hi=Math.max(...vals)+2;return `<svg class="plot" viewBox="0 0 600 190" role="img" aria-label="Biểu đồ lịch sử chỉ số"><line x1="40" y1="15" x2="40" y2="160"/><line x1="40" y1="160" x2="585" y2="160"/><line x1="40" y1="85" x2="585" y2="85"/><text x="4" y="20">${hi.toFixed(0)}</text><text x="4" y="160">${lo.toFixed(0)}</text><polyline points="${rows.map((r,i)=>`${40+i*545/Math.max(rows.length-1,1)},${160-(r.value-lo)/(hi-lo)*145}`).join(' ')}"/><text x="40" y="185">${esc(rows[0].ts_utc.slice(0,16))}</text><text x="430" y="185">${esc(rows.at(-1).ts_utc.slice(0,16))}</text></svg>`;}
function historyPage(){const rows=state.history?.points||[];return `<div class="page-stack">${UI.panel('HISTORY / MEASURED ANALYTICS',`<div class="button-row">${[1,7,30].map(n=>`<button data-range="${n}" class="${state.range===n?'active':''}">${n===1?'24H':n+'D'}</button>`).join('')}<label>METRIC <select id="history-metric" aria-label="Chỉ số lịch sử"><option ${state.historyMetric==='hr'?'selected':''}>hr</option><option ${state.historyMetric==='spo2'?'selected':''}>spo2</option><option ${state.historyMetric==='temp'?'selected':''}>temp</option></select></label><button data-action="load-history">LOAD / LTTB</button></div><p>${esc(state.historyMetric.toUpperCase())} / MEASURED / ${state.range===1?'24H':state.range+'D'}</p>${plot(rows)}<p>Chỉ hiển thị phép đo thực được lưu cục bộ.</p>${state.history?`<pre>${esc(JSON.stringify(state.history.by_source,null,2))}</pre>`:''}`)}</div>`;}
function recordPage(kind){const labels={sleep:['SLEEP LOG','Thời lượng (giờ)','hours'],nutrition:['NUTRITION LOG','Năng lượng (kcal)','calories'],environment:['ENVIRONMENT / RAD','CO₂ (ppm)','co2']};const [title,label,field]=labels[kind];const rows=state.records[kind]||[];return `<div class="page-stack">${UI.panel(title,`<p>Nguồn dữ liệu được lưu theo từng bản ghi. Giá trị tự nhập không được chuyển thành đo thực. ${!state.token?'Demo lưu cục bộ trong trình duyệt.':''}</p><form id="record-form" class="form-grid" data-kind="${kind}"><label>${label}<input name="${field}" type="number" min="0" max="${kind==='sleep'?24:100000}" step="0.1" required></label><label>${kind==='nutrition'?'Nước uống (ml)':'Ghi chú'}<input name="${kind==='nutrition'?'water':'note'}" ${kind==='nutrition'?'type="number" min="0" max="10000"':'maxlength="1000"'}></label><button type="submit">SAVE / SELF-REPORTED</button></form>`)}${UI.panel('LOCAL RECORDS',rows.length?`<table><thead><tr><th>UTC</th><th>DATA</th><th>SOURCE</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.created_at?.slice(0,19))}</td><td>${esc(JSON.stringify(r.payload))}</td><td>${esc(r.source_type)}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">Chưa có bản ghi. Không đủ dữ liệu để đánh giá.</div>')}</div>`;}
function demoInference(modelId){const features=[.2,.4,.6];return {model_id:modelId,model_is_placeholder:true,execution:'browser_demo_only',source_type:'simulated',input:features,score:modelId==='anomaly-demo'?.4:.6,score_unit:'arbitrary_demo_value',explanation:{method:'illustrative_template',feature_importance:[.2,.4,.6],limitations:'Không chạy ONNX, không dùng dữ liệu đo thực; không có giá trị lâm sàng.'}};}
function aiPage(){const blocked=state.token&&!canCrewDetail();return `<div class="page-stack">${UI.panel('LOCAL MODEL REGISTRY',`<p>${blocked?'Vai trò Ground Control Operator không được xem dữ liệu cá nhân hoặc chạy suy luận cho phi hành gia.':state.token?'Checkpoint ONNX mẫu chạy trên backend cục bộ.':'Bản xem thử trong trình duyệt dùng phép tính minh họa. Đăng nhập để chạy checkpoint ONNX cục bộ.'}</p><div class="status-line ${state.token&&!blocked?'normal':'unknown'}">${blocked?'CREW DETAIL ACCESS DENIED':state.token?'LOCAL INFERENCE AVAILABLE':'SIMULATED PREVIEW / NOT AN ONNX RUN'}</div><div class="button-row"><button data-infer="anomaly-demo" ${blocked?'disabled':''}>${state.token?'RUN':'PREVIEW'} ANOMALY DEMO</button><button data-infer="forecast-demo" ${blocked?'disabled':''}>${state.token?'RUN':'PREVIEW'} FORECAST DEMO</button><button data-action="models">MODEL MANIFESTS</button>${!state.token?'<button data-action="login-open">ĐĂNG NHẬP ĐỂ CHẠY ONNX</button>':''}</div><p>Đầu vào minh họa: [0.2, 0.4, 0.6]. Kết quả không dùng để đánh giá sức khỏe.</p>`)}${UI.panel('EXPLAINABILITY / ENGINEERING VIEW',state.lastInference?`<pre>${esc(JSON.stringify(state.lastInference,null,2))}</pre>`:'<p>Chọn mô hình để xem kết quả và giới hạn của bản mẫu.</p>')}</div>`;}
function syncPage(){const ground=state.health?.ground==='connected'?'CONNECTED':'NO CONTACT',service=state.health?.services?.['sync-service']?.status||'unknown',blocked=state.user?.role==='Astronaut';const summary=state.syncStatus||{ground_connected:state.health?.ground==='connected',service,queue:blocked?'Vai trò Astronaut không có quyền vận hành đồng bộ.':state.token?'Chọn READ QUEUE STATUS.':'Đăng nhập vai trò Medical Officer hoặc Ground Control Operator để đọc hàng đợi.'};return `<div class="page-stack">${UI.panel('GROUND CONTROL / STORE & FORWARD',`<div class="status-line ${ground==='CONNECTED'?'normal':'watch'}">${ground==='CONNECTED'?'▣':'△'} GROUND: ${ground} / SYNC SERVICE: ${esc(service.toUpperCase())}</div><p>Dữ liệu được ghi cục bộ trước. Trạng thái gửi chỉ xác nhận khi transport báo thành công.</p><div class="button-row"><button data-action="sync-status" ${blocked?'disabled':''}>${state.token?'READ QUEUE STATUS':'REFRESH SERVICE STATUS'}</button><button data-action="sync-retry" ${!state.token||blocked?'disabled title="Yêu cầu đăng nhập vai trò vận hành"':''}>RETRY PENDING</button>${!state.token?'<button data-action="login-open">ĐĂNG NHẬP ĐỂ ĐỒNG BỘ</button>':''}</div><pre id="sync-result">${esc(JSON.stringify(summary,null,2))}</pre>`)}</div>`;}
function systemPage(){
  const health=state.health||{status:'offline',reason:'Không kết nối được API cục bộ.'};
  const accountRows=(state.accounts||[]).map(a=>`<tr><td>${esc(a.username)}</td><td>${esc(a.role)}</td><td>${esc(state.crews.find(c=>c.id===a.crew_id)?.name||(a.crew_id?'Hồ sơ demo':'—'))}</td></tr>`).join('');
  const crewRows=state.crews.map(c=>`<tr><td>${esc(c.name)}</td><td>${esc(c.callsign)}</td><td>${esc(c.mission_id)}</td></tr>`).join('');
  return `<div class='page-stack'>${UI.panel('SYSTEM HEALTH / SERVICE ISOLATION',`<div class='button-row'><button data-action='refresh-health'>REFRESH HEALTH</button><button data-go='design'>STYLE GUIDE /design</button></div><pre>${esc(JSON.stringify(health,null,2))}</pre>`)}
    ${UI.panel('OPERATOR CONTROLS',`<label><input id='audio' type='checkbox' ${state.audio?'checked':''}> Bật âm báo cục bộ</label><p>Trạng thái lấy từ backend cục bộ.</p><div class='button-row'><button data-action='open-api' ${state.online?'':'disabled'}>OPEN API DOCUMENTATION</button>${state.token?'<button data-action=password-open>ĐỔI MẬT KHẨU</button>':''}</div>`)}
    ${canManageAccounts()?UI.panel('CREW MANAGEMENT / HỒ SƠ PHI HÀNH ĐOÀN',`<p>Tạo hồ sơ trước khi cấp tài khoản Astronaut hoặc nhận phép đo. Không có số liệu đo được tự sinh.</p><button data-action='crew-create-open'>TẠO HỒ SƠ PHI HÀNH ĐOÀN</button>${crewRows?`<table><thead><tr><th>TÊN</th><th>CALLSIGN</th><th>NHIỆM VỤ</th></tr></thead><tbody>${crewRows}</tbody></table>`:'<div class=empty>Chưa có hồ sơ phi hành đoàn.</div>'}`):''}
    ${canManageAccounts()?UI.panel('ACCOUNT MANAGEMENT / ĐĂNG KÝ',`<p>Medical Officer tạo tài khoản và cấp vai trò. Astronaut phải gắn với một hồ sơ phi hành đoàn.</p><div class='button-row'><button data-action='register-open'>TẠO TÀI KHOẢN</button><button data-action='accounts-refresh'>LÀM MỚI DANH SÁCH</button></div>${state.accounts?`<table><thead><tr><th>TÀI KHOẢN</th><th>VAI TRÒ</th><th>PHI HÀNH ĐOÀN</th></tr></thead><tbody>${accountRows}</tbody></table>`:'<p>Chọn LÀM MỚI DANH SÁCH để xem tài khoản.</p>'}`):''}</div>`;
}
function styleGuide(){return `<div class="page-stack">${UI.panel('DESIGN SYSTEM / DAY · NIGHT · RED-LIGHT',`<p>Tokens cục bộ / Times New Roman / không CDN / 48px, chế độ găng tay 64px. Đổi DISPLAY ở thanh trên để kiểm tra.</p><div class="button-row"><button>BUTTON</button><button class="active">ACTIVE</button><button disabled>DISABLED</button><button class="warning">WARNING △</button><button class="caution">CAUTION △</button></div><div class="status-line normal">□ NORMAL / NOMINAL</div><div class="status-line caution">△ WATCH / CAUTION</div><div class="status-line warning">▲ WARNING / CRITICAL</div><div class="status-line unknown">▧ INSUFFICIENT DATA</div>${UI.value('VALUE TILE','—','bpm','NO DATA',false)}<label>TIME RANGE<input type="range" min="1" max="30" value="7" aria-label="Khoảng thời gian mẫu"></label><div class="button-row"><button data-range="1">− RANGE</button><button data-range="7">+ RANGE</button><button id="design-toggle" aria-pressed="false">TOGGLE</button></div>`)}${UI.panel('BODY MAP / PANEL',UI.bodyMap(state.organ))}</div>`;}
function render(){if(typeof page==='number'&&typeof _pMap!=='undefined'&&_pMap[page])state.page=_pMap[page];renderShell();let html;
if(!state.crews.length&&!['dashboard','system','sync','design'].includes(state.page)){html=`<div class="page-stack">${UI.panel('CHƯA CÓ HỒ SƠ PHI HÀNH ĐOÀN',`<div class="status-line unknown">▧ NO CREW DATA</div><p>${state.token?'Medical Officer có thể tạo hồ sơ mới trong SYSTEM.':'Đăng nhập để xem hồ sơ được cấp.'} Chưa có số liệu đo thực để hiển thị.</p><div class="button-row">${state.token?'':'<button data-action="login-open">ĐĂNG NHẬP</button>'}<button data-go="system">MỞ SYSTEM</button></div>`)}</div>`;}else switch(state.page){
case 'dashboard':html=dashboard();break;
case 'vitals':html=`<div class="page-stack">${UI.panel('CURRENT TELEMETRY / SOURCE & FRESHNESS',metricTable())}${UI.panel('ECG / WAVEFORM','<p>Chưa có đoạn sóng ECG đo thực. Khung sóng bên phải để trống cho đến khi có dữ liệu cảm biến.</p><button data-go="history">HISTORY</button>')}</div>`;break;
case 'organs':html=`<div class="page-stack">${UI.panel('SYSTEM DATA AVAILABILITY',`<div class="button-row">${organs.map(([id,n])=>`<button data-organ="${id}" class="${id===state.organ?'active':''}">${n}</button>`).join('')}</div><div class="status-line ${organStatus(state.organ)==='warning'?'warning':'unknown'}">${statusLabel(organStatus(state.organ))}</div><p>Trạng thái dựa trên phép đo thực và quy tắc đã cấu hình. Thiếu dữ liệu được hiển thị riêng.</p>${UI.bodyMap(state.organ)}<button data-action="organ-detail">XEM CHI TIẾT HỆ CƠ QUAN</button>`)}</div>`;break;
case 'sleep':case 'nutrition':case 'environment':html=recordPage(state.page);break;
case 'ai':html=aiPage();break;
case 'alerts':html=`<div class="page-stack">${UI.panel('ALERTS / DETERMINISTIC RULE ENGINE',`<p>ACK xác nhận đã xem, không tự giải quyết cảnh báo. WHY? hiển thị quy tắc và nguồn.</p>${alertValues().map(alertHTML).join('')||'<div class="empty">Không có cảnh báo.</div>'}`)}</div>`;break;
case 'history':html=historyPage();break;
case 'reports':if(state.token&&!canCrewDetail()){html=`<div class="page-stack">${UI.panel('REPORTS / ACCESS',`<div class="status-line unknown">CREW DETAIL ACCESS DENIED</div><p>Ground Control Operator chỉ xem trạng thái nhiệm vụ và đồng bộ; báo cáo sức khỏe cá nhân cần quyền Medical Officer.</p><button data-go="sync">OPEN SYNC</button>`)}</div>`;break;}html=`<div class="page-stack">${UI.panel('REPORT PREVIEW / LATEST PARAMETERS',`<p>CREW: ${esc(selected().name)} / ${state.token?'AUTHENTICATED LOCAL DATA':'SIMULATED DEMO DATA'} / UTC ${esc(new Date().toISOString())}</p>${metricTable()}<p>Báo cáo ghi rõ nguồn, thời gian, chất lượng và trạng thái dữ liệu. Hỗ trợ giám sát, không thay thế chẩn đoán y khoa.</p><div class="button-row"><button data-export="csv">EXPORT CSV</button><button data-export="pdf">${state.token?'EXPORT PDF':'PRINT / SAVE PDF'}</button><button data-action="event">MARK EVENT</button></div>`)}${UI.panel('SELF-REPORTED EVENTS',reportEvents().length?`<table><thead><tr><th>UTC</th><th>NOTE</th><th>SOURCE</th></tr></thead><tbody>${reportEvents().map(r=>`<tr><td>${esc(r.created_at)}</td><td>${esc(r.note)}</td><td>${esc(r.source_type)}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">Chưa có event cho phi hành gia này.</div>')}</div>`;break;
case 'assistant':html=`<div class="page-stack">${UI.panel('LOCAL ASSISTANT / RULES & CONTROLLED TEMPLATES',`<p>Tiếng Việt / English. Không dùng LLM hoặc API đám mây. Hỗ trợ chỉ số mới nhất, cảnh báo, HR 7 ngày, ECG, giấc ngủ, báo cáo.</p><form id="assistant-form" class="form-grid"><label class="wide">Câu hỏi<input name="query" placeholder="So sánh HR 7 ngày / latest vitals" maxlength="2000" required></label><button>QUERY / ENTER</button></form><div id="assistant-result" aria-live="polite"></div>`)}</div>`;break;
case 'sync':html=syncPage();break;
case 'design':html=styleGuide();break;
default:html=systemPage();}
$('#content').innerHTML=html;renderEpoch++;
const bodyMap=$('#body-map-viewport');
if(bodyMap?.classList?.toggle){bodyMap.classList.toggle('expanded',state.bodyExpanded);bodyMap.querySelector?.('.model-expand-control')?.setAttribute?.('aria-pressed',String(state.bodyExpanded));}
if(['dashboard','organs','design'].includes(state.page)&&typeof initBodyInteraction==='function')initBodyInteraction();
}
function initBodyInteraction(){
  const host=document.querySelector('#body-model-stage');
  if(!host)return;
  const fallback=()=>{if(!host.isConnected||host.classList.contains('model-ready'))return;host.classList.add('model-unavailable');const status=host.querySelector('#model-loading'),image=host.querySelector('.model-fallback');if(status)status.textContent='Trình xem 3D chưa sẵn sàng; đang dùng ảnh cơ thể dự phòng.';if(image)image.hidden=false;};
  if(window.ManViewer?.mount){try{window.ManViewer.mount(host);setTimeout(fallback,8000);}catch(error){console.error('3D viewer failed',error);fallback();}}
  else fallback();
}
function go(page){if(!pages.some(p=>p[0]===page))return;if(page!==state.page){state.navHistory.push(state.page);state.page=page;state.bodyExpanded=false;}history.replaceState(null,'','#'+page);render();if(page==='system'&&canManageAccounts())loadAccounts().catch(e=>toast(e.message));if(!state.crews.length)return;if(['sleep','nutrition','environment'].includes(page))loadRecords(page).catch(e=>toast(e.message));if(page==='reports'&&state.token&&canCrewDetail())loadRecords('event').catch(e=>toast(e.message));if(page==='history'&&state.token&&canCrewDetail())loadHistory().catch(e=>toast(e.message));}
async function updateHealth(){try{const r=await fetch(API+'/health',{signal:AbortSignal.timeout(2500)});if(!r.ok)throw Error('offline');state.health=await r.json();state.online=true;}catch{state.health=null;state.online=false;}renderShell();}
async function refreshCrew(){if(!state.token||!state.crews.length){state.vitals=[];state.alerts=[];state.bodyStatus=null;render();return;}if(state.user?.role==='Ground Control Operator'){state.vitals=[];state.alerts=[];state.bodyStatus=null;go('sync');return;}const id=selected().id;const [v,a,b]=await Promise.all([request('/vitals/'+id),request('/alerts?crew_id='+id),request('/body/'+id+'/status')]);if(selected().id!==id)return;state.vitals=v;state.alerts=a;state.bodyStatus=b;render();}
function openLive(){state.socket?.close();if(!state.token||!state.crews.length||state.user?.role==='Ground Control Operator')return;const wsurl=API?API.replace('http:','ws:')+'/ws/live':location.origin.replace(/^http/,'ws')+'/ws/live';const socket=new WebSocket(wsurl);state.socket=socket;socket.onopen=()=>socket.send(JSON.stringify({token:state.token,crew_id:selected().id}));socket.onmessage=event=>{if(state.socket!==socket)return;const data=JSON.parse(event.data);state.vitals=data.vitals;state.alerts=data.alerts;renderTelemetry();};socket.onerror=()=>toast('Luồng live chưa sẵn sàng. Dữ liệu cuối được giữ kèm nhãn nguồn/thời gian.');}
async function loginModal(){
  let status;
  try{status=await request('/auth/setup-status');}
  catch{modal('LOCAL AUTHENTICATION','<p>Không kết nối được backend cục bộ. Hãy chạy start-local.ps1 rồi thử lại.</p>');return;}
  if(status.required){
    modal('FIRST LOCAL ACCOUNT / KHỞI TẠO TÀI KHOẢN',`<p>Chưa có tài khoản trên thiết bị. Tạo tài khoản Medical Officer đầu tiên bằng mật khẩu do bạn chọn.</p><form id="setup-form" class="form-grid"><label>Tên đăng nhập<input name="username" autocomplete="username" value="medical" required minlength="3" maxlength="80"></label><label>Mật khẩu mới (ít nhất 12 ký tự)<input name="password" type="password" autocomplete="new-password" required minlength="12" maxlength="256"></label><label class="wide">Nhập lại mật khẩu<input name="confirm_password" type="password" autocomplete="new-password" required minlength="12" maxlength="256"></label><button type="submit">TẠO TÀI KHOẢN & ĐĂNG NHẬP</button><span id="login-error" class="warning wide" role="alert"></span></form>`);
    return;
  }
  modal('LOCAL AUTHENTICATION / ĐĂNG NHẬP',`<p>Đăng nhập tài khoản cục bộ đã tạo trên thiết bị.</p><form id="login-form" class="form-grid"><label>Tài khoản<input name="username" autocomplete="username" required maxlength="80"></label><label>Mật khẩu<input name="password" type="password" autocomplete="current-password" required maxlength="256"></label><button type="submit">ĐĂNG NHẬP</button><span id="login-error" class="warning wide" role="alert"></span></form><p>Chưa có tài khoản? <button data-action="register-open">ĐĂNG KÝ TRÊN APP</button></p>`);
}
function selfRegistrationModal(){modal('ĐĂNG KÝ TRÊN APP',`<p>Tạo tài khoản cá nhân cho bản demo cục bộ. Hồ sơ mới chưa có dữ liệu đo và không được xem dữ liệu của phi hành đoàn hiện hữu.</p><form id="self-register-form" class="form-grid"><label>Tên đăng nhập<input name="username" autocomplete="username" required minlength="3" maxlength="80"></label><label>Tên hiển thị<input name="display_name" autocomplete="name" required minlength="1" maxlength="80"></label><label>Mật khẩu (ít nhất 12 ký tự)<input name="password" type="password" autocomplete="new-password" required minlength="12" maxlength="256"></label><label>Nhập lại mật khẩu<input name="confirm_password" type="password" autocomplete="new-password" required minlength="12" maxlength="256"></label><button type="submit">TẠO TÀI KHOẢN & ĐĂNG NHẬP</button><span id="self-register-error" class="warning wide" role="alert"></span></form>`);}
function registrationModal(){const options=state.crews.map(c=>`<option value="${esc(c.id)}">${esc(c.name||c.callsign)} / ${esc(c.callsign)}</option>`).join('');modal('ĐĂNG KÝ / CẤP TÀI KHOẢN',`<p>Tạo tài khoản cục bộ và cấp vai trò. Mật khẩu cần ít nhất 12 ký tự.</p><form id="register-form" class="form-grid"><label>Tên đăng nhập<input name="username" autocomplete="off" required minlength="3" maxlength="80"></label><label>Vai trò<select name="role" id="register-role"><option value="Astronaut">Astronaut</option><option value="Medical Officer">Medical Officer</option><option value="Ground Control Operator">Ground Control Operator</option></select></label><label class="wide">Thành viên phi hành đoàn (bắt buộc với Astronaut)<select name="crew_id" id="register-crew" required><option value="">— Chọn thành viên —</option>${options}</select></label><label>Mật khẩu<input name="password" type="password" autocomplete="new-password" required minlength="12" maxlength="256"></label><label>Nhập lại mật khẩu<input name="confirm_password" type="password" autocomplete="new-password" required minlength="12" maxlength="256"></label><button type="submit">TẠO TÀI KHOẢN</button><span id="register-error" class="warning wide" role="alert"></span></form>`);}
function crewCreationModal(){modal('TẠO HỒ SƠ PHI HÀNH ĐOÀN',`<p>Hồ sơ mới bắt đầu trống. Chỉ số sinh tồn xuất hiện khi có phép đo thực được nhận qua backend.</p><form id="crew-create-form" class="form-grid"><label>Tên hiển thị<input name="name" required minlength="1" maxlength="80"></label><label>Callsign<input name="callsign" required minlength="1" maxlength="20"></label><label class="wide">Mã nhiệm vụ<input name="mission_id" required minlength="1" maxlength="80"></label><button type="submit">TẠO HỒ SƠ</button><span id="crew-create-error" class="warning wide" role="alert"></span></form>`);}
async function loadAccounts(){if(!canManageAccounts())return;state.accounts=await request('/auth/accounts');if(state.page==='system')render();}
async function finishLogin(tokens){state.token=tokens.access_token;state.refresh=tokens.refresh_token;try{state.user=await request('/auth/me');state.crews=await request('/crew');state.crew=0;state.lastInference=null;state.syncStatus=null;await refreshCrew();openLive();await updateHealth();render();$('#modal').close();if(state.page==='system'&&canManageAccounts())loadAccounts().catch(e=>toast(e.message));toast('Đăng nhập thành công với vai trò '+(state.user?.role||'Medical Officer')+'!');}catch(error){clearSession();throw error;}}
async function ack(id){if(!state.token){await loginModal();return;}await request('/alerts/'+id+'/acknowledge',{method:'POST'});await refreshCrew();}
async function master(levels){const pending=alertValues().filter(a=>levels.includes(a.level)&&a.status==='open');for(const a of pending)await ack(a.id);if(!pending.length)toast('Không có cảnh báo chưa xác nhận ở mức này.');}
async function loadHistory(){state.history=await request(`/vitals/${selected().id}/history?metric=${state.historyMetric}&days=${state.range}&points=300`);if(state.page==='history')render();}
async function loadRecords(kind){if(state.token)state.records[kind]=await request('/records/'+kind+'?crew_id='+selected().id);else{try{state.records[kind]=JSON.parse(localStorage.getItem('astro-v3-'+selected().id+'-'+kind)||'[]');}catch{state.records[kind]=[];}}if(state.page===kind||(kind==='event'&&state.page==='reports'))render();}
async function exportData(format){if(!state.token){if(format==='pdf'){if(window.electronAPI?.exportDemoPdf){const result=await window.electronAPI.exportDemoPdf();if(result.error)throw Error(result.error);if(result.success)toast('Đã lưu PDF mô phỏng.');}else window.print();return;}const data='\ufeffUTC,metric,value,unit,source_type\r\n'+values().map(r=>[r.ts_utc,r.metric,r.value,r.unit,r.source_type].map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n');return saveBlob(new Blob([data],{type:'text/csv;charset=utf-8'}),'AstroHealth-SIMULATED.csv');}const response=await fetch(API+`/api/v1/reports/${selected().id}/export?format=${format}`,{headers:{Authorization:'Bearer '+state.token}});if(!response.ok)throw Error('Không thể xuất báo cáo, vui lòng đăng nhập lại.');saveBlob(await response.blob(),'AstroHealth.'+format);}
function saveBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Đã tạo tệp xuất có nhãn nguồn dữ liệu.');}
function localAssistant(query){const q=query.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d').toLowerCase();if(/chan doan|dieu tri|thuoc|diagnos|treatment/.test(q))return {answer:'Chỉ hỗ trợ giám sát; không chẩn đoán hoặc chỉ định điều trị.'};return {answer:'Chưa có hồ sơ và phép đo thực để truy vấn. Đăng nhập và chọn phi hành gia trước.'};}
function demoEvents(){try{return JSON.parse(localStorage.getItem('astro-v3-'+selected().id+'-events')||'[]');}catch{return [];}}
function reportEvents(){return state.token?(state.records.event||[]).map(r=>({created_at:r.created_at,note:r.payload?.note,source_type:r.source_type})):demoEvents().map(r=>({...r,source_type:'self_reported / demo'}));}
document.addEventListener('click',async event=>{const b=event.target.closest('button,[data-organ]');if(!b)return;try{
if(b.dataset.go)return go(b.dataset.go);
 if(b.dataset.crew!==undefined){state.crew=Number(b.dataset.crew);state.vitals=[];state.alerts=[];state.bodyStatus=null;state.history=null;state.lastInference=null;state.records={};render();if(state.token){await refreshCrew();openLive();}if(['sleep','nutrition','environment'].includes(state.page)&&canCrewDetail())await loadRecords(state.page);if(state.page==='reports'&&state.token&&canCrewDetail())await loadRecords('event');return;}
if(b.dataset.organ){state.organ=b.dataset.organ;render();return;}
if(b.dataset.ack)return await ack(b.dataset.ack);
if(b.dataset.why){const alert=alertValues().find(a=>a.id===b.dataset.why);return modal('WHY / DETERMINISTIC ALERT',`<p>Cảnh báo được tạo bởi quy tắc hoặc tình trạng liên lạc.</p><pre>${esc(JSON.stringify(alert,null,2))}</pre>`);}
if(b.dataset.range){state.range=Number(b.dataset.range);state.history=null;if(state.token)await loadHistory();else render();return;}
if(b.dataset.export)return await exportData(b.dataset.export);
 if(b.dataset.infer){state.lastInference=state.token?await request('/ai/inference',{method:'POST',body:JSON.stringify({crew_id:selected().id,model_id:b.dataset.infer,features:[.2,.4,.6]})}):demoInference(b.dataset.infer);render();return;}
const action=b.dataset.action||b.id;
switch(action){
case 'back':{const previous=state.navHistory.pop();if(previous){state.page=previous;render();}break;}
case 'next':go(pages[(pages.findIndex(p=>p[0]===state.page)+1)%pages.length][0]);break;
case 'freeze':state.freeze=!state.freeze;$('#freeze').setAttribute('aria-pressed',state.freeze);$('#freeze').textContent=state.freeze?'FROZEN [F]':'FREEZE [F]';break;
case 'cursor':state.cursor=!state.cursor;$('#cursor').setAttribute('aria-pressed',state.cursor);break;
case 'gloves':document.body.classList.toggle('gloves');b.setAttribute('aria-pressed',document.body.classList.contains('gloves'));break;
case 'master-warning':await master(['Critical']);break;
case 'master-caution':await master(['Warning','Watch']);break;
case 'login-open':if(state.token){try{await request('/auth/logout',{method:'POST'});}finally{clearSession();render();}}else await loginModal();break;
case 'register-open':if(canManageAccounts()){registrationModal();}else if(!state.token){const setup=await request('/auth/setup-status');if(setup.required)await loginModal();else if(state.health?.mode==='operational')modal('ĐĂNG KÝ TÀI KHOẢN','<p>Chế độ vận hành yêu cầu Medical Officer tạo và cấp quyền tài khoản trong SYSTEM.</p>');else selfRegistrationModal();}break;
case 'crew-create-open':if(canManageAccounts())crewCreationModal();break;
case 'accounts-refresh':await loadAccounts();break;
case 'password-open':modal('ĐỔI MẬT KHẨU CỤC BỘ',`<form id="password-form" class="form-grid"><label class="wide">Mật khẩu hiện tại<input name="old_password" type="password" autocomplete="current-password" required></label><label>Mật khẩu mới (ít nhất 12 ký tự)<input name="new_password" type="password" autocomplete="new-password" required minlength="12" maxlength="256"></label><label>Nhập lại mật khẩu mới<input name="confirm_password" type="password" autocomplete="new-password" required minlength="12" maxlength="256"></label><button type="submit">LƯU MẬT KHẨU MỚI</button><span id="password-error" class="warning wide" role="alert"></span></form>`);break;
case 'modal-close':$('#modal').close();break;
case 'body-zoom':{
  state.bodyExpanded=!state.bodyExpanded;
  const map=$('#body-map-viewport');
  map?.classList.toggle('expanded',state.bodyExpanded);
  map?.querySelector('.model-expand-control')?.setAttribute('aria-pressed',String(state.bodyExpanded));
  break;
}
case 'model-credit':modal('MODEL MAN / GIẤY PHÉP',`<p>Mô hình “Man” của <b>mattmerk</b> trên BlendSwap, giấy phép Creative Commons Attribution-ShareAlike 3.0.</p><p>AstroHealth đã chuyển tệp Blender gốc sang GLB và hiển thị dạng lưới kỹ thuật. Mô hình này chỉ minh họa vị trí, không chứa cấu trúc giải phẫu được kiểm chứng.</p><p><a href="https://blendswap.com/blend/8811" target="_blank" rel="noopener noreferrer">Trang mô hình gốc</a> · <a href="https://creativecommons.org/licenses/by-sa/3.0/" target="_blank" rel="noopener noreferrer">Điều khoản CC BY-SA 3.0</a></p>`);break;
case 'organ-detail':{
  const detail=state.bodyStatus?.[state.organ];
  modal('CHI TIẾT HỆ CƠ QUAN / '+state.organ.toUpperCase(),`<div class="status-line ${organStatus(state.organ)==='warning'?'warning':'unknown'}">${statusLabel(organStatus(state.organ))}</div><p>Chỉ số đo thực của hệ này:</p><pre>${esc(JSON.stringify(detail?.metrics||[],null,2))}</pre><p>Thiếu dữ liệu hoặc thiếu đánh giá đã kiểm chứng không được coi là bình thường.</p>`);
  break;
}
case 'event':modal('MARK EVENT / SELF-REPORTED','<form id="event-form" class="form-grid"><label class="wide">Ghi chú<textarea name="text" required maxlength="1000"></textarea></label><button>SAVE EVENT</button></form>');break;
case 'load-history':if(state.token)await loadHistory();else render();break;
 case 'models':modal('MODEL MANIFESTS',`<pre>${esc(JSON.stringify(state.token?await request('/ai/models'):[{id:'anomaly-demo',status:'preview only',model_is_placeholder:true},{id:'forecast-demo',status:'preview only',model_is_placeholder:true}],null,2))}</pre>`);break;
 case 'sync-status':if(!state.token){await updateHealth();state.syncStatus={checked_at:new Date().toISOString(),ground_connected:state.health?.ground==='connected',service:state.health?.services?.['sync-service']?.status||'offline',queue:'Yêu cầu đăng nhập vai trò Medical Officer hoặc Ground Control Operator.'};}else{state.syncStatus=await request('/sync/status');}render();break;
 case 'sync-retry':if(!state.token){await loginModal();break;}await request('/sync/retry',{method:'POST'});state.syncStatus=await request('/sync/status');render();toast('Đã đánh dấu thử lại cục bộ; chưa xác nhận gửi tới Ground.');break;
case 'refresh-health':await updateHealth();render();break;
case 'open-api':if(state.online)window.open(API+'/docs','_blank','noopener');else toast('Backend chưa chạy: khởi động start-local.ps1 để mở /docs.');break;
case 'design-toggle':b.setAttribute('aria-pressed',b.getAttribute('aria-pressed')!=='true');break;
}
}catch(error){toast(error.message);}});
document.addEventListener('submit',async event=>{event.preventDefault();const form=event.target,data=Object.fromEntries(new FormData(form));try{
 if(form.id==='login-form'){const tokens=await request('/auth/login',{method:'POST',body:JSON.stringify(data)});await finishLogin(tokens);}
 if(form.id==='setup-form'){if(data.password!==data.confirm_password)throw Error('Hai mật khẩu không khớp.');const tokens=await request('/auth/setup',{method:'POST',body:JSON.stringify({username:data.username,password:data.password})});await finishLogin(tokens);}
 if(form.id==='self-register-form'){if(data.password!==data.confirm_password)throw Error('Hai mật khẩu không khớp.');const tokens=await request('/auth/self-register',{method:'POST',body:JSON.stringify({username:data.username,display_name:data.display_name,password:data.password})});await finishLogin(tokens);toast('Đã tạo hồ sơ demo cá nhân. Chưa có dữ liệu đo.');}
  if(form.id==='register-form'){if(data.password!==data.confirm_password)throw Error('Hai mật khẩu không khớp.');if(data.role==='Astronaut'&&!data.crew_id)throw Error('Chọn thành viên phi hành đoàn cho tài khoản Astronaut.');const account=await request('/auth/register',{method:'POST',body:JSON.stringify({username:data.username,password:data.password,role:data.role,crew_id:data.role==='Astronaut'?data.crew_id:null})});$('#modal').close();toast('Đã tạo tài khoản '+account.username+' / '+account.role+'.');loadAccounts().catch(e=>toast(e.message));}
  if(form.id==='crew-create-form'){const profile=await request('/crew',{method:'POST',body:JSON.stringify(data)});state.crews=await request('/crew');state.crew=state.crews.findIndex(c=>c.id===profile.id);if(state.crew<0)state.crew=0;$('#modal').close();await refreshCrew();openLive();toast('Đã tạo hồ sơ trống '+profile.name+'.');}
 if(form.id==='password-form'){if(data.new_password!==data.confirm_password)throw Error('Hai mật khẩu mới không khớp.');await request('/auth/password',{method:'POST',body:JSON.stringify({old_password:data.old_password,new_password:data.new_password})});clearSession();$('#modal').close();render();toast('Đã đổi mật khẩu. Vui lòng đăng nhập lại.');}
if(form.id==='record-form'){const kind=form.dataset.kind;for(const k of ['hours','water','calories','co2'])if(data[k]!==undefined)data[k]=Number(data[k]);if(state.token)await request('/records/'+kind,{method:'POST',body:JSON.stringify({crew_id:selected().id,source_type:'self_reported',payload:data})});else{const rows=state.records[kind]||[];rows.unshift({created_at:new Date().toISOString(),source_type:'self_reported',payload:data});localStorage.setItem('astro-v3-'+selected().id+'-'+kind,JSON.stringify(rows));}await loadRecords(kind);toast('Đã lưu / SELF-REPORTED');}
if(form.id==='assistant-form'){const result=state.token?await request('/assistant/query',{method:'POST',body:JSON.stringify({crew_id:selected().id,query:data.query})}):localAssistant(data.query);$('#assistant-result').innerHTML=`<p>${esc(result.answer)}</p>${result.data?`<pre>${esc(JSON.stringify(result.data,null,2))}</pre>`:''}`;}
 if(form.id==='event-form'){if(state.token){await request('/records/event',{method:'POST',body:JSON.stringify({crew_id:selected().id,source_type:'self_reported',payload:{note:data.text}})});await loadRecords('event');}else{const rows=demoEvents();rows.unshift({created_at:new Date().toISOString(),note:data.text});localStorage.setItem('astro-v3-'+selected().id+'-events',JSON.stringify(rows));}$('#modal').close();if(state.page==='reports')render();toast('Đã ghi sự kiện / SELF-REPORTED');}
}catch(error){if(['login-form','setup-form'].includes(form.id))$('#login-error').textContent=error.message;else if(form.id==='self-register-form')$('#self-register-error').textContent=error.message;else if(form.id==='register-form')$('#register-error').textContent=error.message;else if(form.id==='crew-create-form')$('#crew-create-error').textContent=error.message;else if(form.id==='password-form')$('#password-error').textContent=error.message;else toast(error.message);}});
document.addEventListener('change',event=>{if(event.target.id==='theme'){document.documentElement.dataset.theme=event.target.value;draw();try{localStorage.setItem('astro-theme',event.target.value);}catch{}}if(event.target.id==='register-role'){const crew=$('#register-crew');crew.required=event.target.value==='Astronaut';crew.disabled=event.target.value!=='Astronaut';if(crew.disabled)crew.value='';}if(event.target.id==='history-metric'){state.historyMetric=event.target.value;state.history=null;if(state.token)loadHistory().catch(error=>toast(error.message));else render();}if(event.target.id==='audio'){state.audio=event.target.checked;alertSound();}});
if($('#dim')?.addEventListener)$('#dim').addEventListener('input',event=>{const fc=document.querySelector('.flight-console');if(fc)fc.style.opacity=Number(event.target.value)/100;});
document.addEventListener('keydown',event=>{if(event.altKey||event.ctrlKey||event.metaKey||/INPUT|TEXTAREA|SELECT/.test(event.target.tagName))return;if($('#modal').open)return;const key=event.key.toLowerCase();if(key==='escape'&&state.bodyExpanded){event.preventDefault();state.bodyExpanded=false;$('#body-map-viewport')?.classList.remove('expanded');$('#body-map-viewport .model-expand-control')?.setAttribute('aria-pressed','false');return;}const keys={h:'dashboard',v:'vitals',a:'alerts',x:'ai',t:'history',r:'reports',s:'sleep',n:'nutrition',e:'environment',i:'assistant',y:'sync',z:'system',d:'design',o:'organs'};if(keys[key]){event.preventDefault();go(keys[key]);}else{const id={f:'freeze',u:'cursor',g:'gloves',w:'master-warning',c:'master-caution',l:'login-open'}[key];if(id){event.preventDefault();$('#'+id).click();}if(key===']'){event.preventDefault();document.querySelector('[data-action="next"]').click();}if(key==='escape')document.querySelector('[data-action="back"]').click();}});
function draw(){
  const canvas=$('#ecg');if(!canvas?.getContext)return;
  const rect=canvas.getBoundingClientRect?canvas.getBoundingClientRect():{width:300,height:88};
  const dpr=typeof devicePixelRatio!=='undefined'?devicePixelRatio:1;
  if(canvas.width!==Math.round(rect.width*dpr)||canvas.height!==Math.round(rect.height*dpr)){canvas.width=Math.round(rect.width*dpr);canvas.height=Math.round(rect.height*dpr);}
  const ctx=canvas.getContext('2d');if(!ctx)return;
  const css=typeof getComputedStyle==='function'?getComputedStyle(document.documentElement):{};
  ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,rect.width,rect.height);
  ctx.strokeStyle=css.getPropertyValue?css.getPropertyValue('--frame'):'#333';ctx.lineWidth=.5;ctx.beginPath();
  for(let x=0;x<rect.width;x+=20){ctx.moveTo(x,0);ctx.lineTo(x,rect.height);}
  for(let y=0;y<rect.height;y+=20){ctx.moveTo(0,y);ctx.lineTo(rect.width,y);}ctx.stroke();
  ctx.fillStyle=css.getPropertyValue?css.getPropertyValue('--muted'):'#8b96a1';ctx.font='10px monospace';ctx.fillText('NO MEASURED ECG DATA',12,rect.height/2);
}
function tick(){const date=new Date();$('#utc').textContent=date.toISOString().slice(11,19)+' UTC';$('#mission-time').textContent='MET —';if(state.token){for(const r of state.vitals)r.stale=Date.now()-Date.parse(r.ts_utc)>60000;renderTelemetry();}}
try{const theme=localStorage.getItem('astro-theme');if(['day','night','red'].includes(theme)){$('#theme').value=theme;document.documentElement.dataset.theme=theme;}}catch{}
const initial=location.pathname==='/design'?'design':location.hash.slice(1);if(pages.some(p=>p[0]===initial))state.page=initial;
if(typeof window!=='undefined'&&window.addEventListener)window.addEventListener('hashchange',()=>go(location.hash.slice(1)));
if(typeof window!=='undefined')window.navigateAstro=page=>go(typeof page==='number'?['vitals','organs','assistant','reports','dashboard','system'][page]||'dashboard':page);
render();tick();if(typeof setInterval==='function'){setInterval(tick,1000);setInterval(updateHealth,15000);}updateHealth();if(typeof requestAnimationFrame==='function')requestAnimationFrame(draw);if(typeof window!=='undefined'&&window.addEventListener)window.addEventListener('resize',draw);
